css:
.gal-factura { font-size: 12px; color: #222; }
.gal-header { display: flex; justify-content: space-between; border-bottom: 2px solid #222; padding-bottom: 8px; margin-bottom: 10px; }
.gal-empresa { font-size: 18px; font-weight: 700; }
.gal-doc { text-align: right; }
.gal-titulo { font-size: 16px; font-weight: 700; letter-spacing: 2px; }
.gal-muted { color: #666; }
.gal-no-cert { border: 2px dashed #b45309; color: #b45309; font-weight: 700; text-align: center; padding: 6px; margin: 8px 0; }
.gal-cliente, .gal-items, .gal-totales { width: 100%; border-collapse: collapse; margin-bottom: 10px; }
.gal-cliente td { padding: 2px 4px; }
.gal-items th { border-bottom: 1px solid #222; text-align: left; padding: 4px; }
.gal-items td { border-bottom: 1px solid #ddd; padding: 4px; }
.gal-r { text-align: right !important; }
.gal-totales { width: 50%; margin-left: 50%; }
.gal-totales td { padding: 2px 4px; }
.gal-total td { font-size: 15px; font-weight: 700; border-top: 1px solid #222; }
.gal-subtitulo { font-weight: 700; margin: 6px 0; }
.gal-fel { display: flex; justify-content: space-between; align-items: center; border-top: 1px solid #222; padding-top: 8px; font-size: 11px; }
.gal-qr { width: 90px; height: 90px; }
.gal-pie { text-align: center; color: #666; margin-top: 12px; }

html:
{%- set bfel = frappe.db.get_value("BFEL Settings", {"company": doc.company, "enabled": 1}, ["company_nit", "nombrecomercial"], as_dict=True) or {} -%}
{%- set principales = ["Cafetería", "Obras de arte", "Eventos – boletos", "Eventos – alquileres"] -%}
{%- set ns = namespace(origenes=principales[:], modos=[]) -%}
{%- for f in doc.origenes -%}
	{%- if not f.es_egreso and f.origen not in ns.origenes -%}{%- set ns.origenes = ns.origenes + [f.origen] -%}{%- endif -%}
	{%- if f.modo_pago not in ns.modos -%}{%- set ns.modos = ns.modos + [f.modo_pago] -%}{%- endif -%}
{%- endfor -%}
{%- macro dinero(v) -%}{{ frappe.utils.fmt_money(v or 0, currency="GTQ") }}{%- endmacro -%}
{%- macro etiqueta(o) -%}{{ o }}{% if o == "Eventos – boletos" and doc.boletos_vendidos %} ({{ doc.boletos_vendidos }} boletos){% endif %}{%- endmacro -%}
<div class="gal-factura">
	<div class="gal-header">
		<div>
			<div class="gal-empresa">{{ bfel.nombrecomercial or doc.company }}</div>
			{% if bfel.company_nit %}<div class="gal-muted">NIT {{ bfel.company_nit }}</div>{% endif %}
		</div>
		<div class="gal-doc">
			<div class="gal-titulo">CIERRE DE CAJA</div>
			<div>{{ doc.name }}</div>
			<div class="gal-muted">{{ frappe.utils.formatdate(doc.fecha) }} · {{ frappe.db.get_value("User", doc.cajero, "full_name") or doc.cajero }}</div>
		</div>
	</div>
	{% if doc.docstatus == 0 %}<div class="gal-no-cert">BORRADOR &mdash; CIERRE NO VALIDADO</div>{% endif %}

	<table class="gal-cliente">
		<tr><td class="gal-muted">Facturas emitidas</td><td>{{ doc.num_facturas }}</td>
			<td class="gal-muted">Total facturado</td><td class="gal-r">{{ dinero(doc.total_facturado) }}</td></tr>
		<tr><td class="gal-muted">Boletos vendidos</td><td>{{ doc.boletos_vendidos or 0 }}</td>
			<td class="gal-muted">Saldo pendiente de las facturas del día</td><td class="gal-r">{{ dinero(doc.ventas_pendientes) }}</td></tr>
	</table>

	<div class="gal-subtitulo">Resumen por área</div>
	<table class="gal-items">
		<thead><tr><th>Área</th>{% for modo in ns.modos %}<th class="gal-r">{{ modo }}</th>{% endfor %}<th class="gal-r">Total</th></tr></thead>
		<tbody>
		{% for o in ns.origenes %}
			{%- set fila = doc.origenes | selectattr("origen", "equalto", o) | list -%}
			<tr><td>{{ etiqueta(o) }}</td>
			{% for modo in ns.modos %}<td class="gal-r">{{ dinero(fila | selectattr("modo_pago", "equalto", modo) | sum(attribute="monto")) }}</td>{% endfor %}
			<td class="gal-r"><b>{{ dinero(fila | sum(attribute="monto")) }}</b></td></tr>
		{% endfor %}
		{%- set egresos = doc.origenes | selectattr("es_egreso") | list -%}
		{% if egresos %}
			<tr><td>(&minus;) Pagos a artistas</td>
			{% for modo in ns.modos %}<td class="gal-r">{{ dinero(egresos | selectattr("modo_pago", "equalto", modo) | sum(attribute="monto")) }}</td>{% endfor %}
			<td class="gal-r">{{ dinero(egresos | sum(attribute="monto")) }}</td></tr>
		{% endif %}
		</tbody>
	</table>

	<div class="gal-subtitulo">Cuadre por forma de pago</div>
	<table class="gal-items">
		<thead><tr><th>Forma de pago</th><th class="gal-r">Cobrado</th><th class="gal-r">Pagos a artistas</th><th class="gal-r">Esperado</th><th class="gal-r">Contado</th><th class="gal-r">Diferencia</th></tr></thead>
		<tbody>
		{% for p in doc.pagos %}
			<tr><td>{{ p.modo_pago }}</td><td class="gal-r">{{ dinero(p.ingresos) }}</td><td class="gal-r">{{ dinero(p.egresos) }}</td>
				<td class="gal-r">{{ dinero(p.esperado) }}</td><td class="gal-r">{{ dinero(p.contado) }}</td><td class="gal-r">{{ dinero(p.diferencia) }}</td></tr>
		{% endfor %}
		</tbody>
	</table>
	<table class="gal-totales">
		<tr><td>Total esperado</td><td class="gal-r">{{ dinero(doc.total_esperado) }}</td></tr>
		<tr><td>Total contado</td><td class="gal-r">{{ dinero(doc.total_contado) }}</td></tr>
		<tr class="gal-total"><td>Diferencia</td><td class="gal-r">{{ dinero(doc.diferencia) }}</td></tr>
	</table>
	{% if doc.observaciones %}<div class="gal-subtitulo">Observaciones</div><div>{{ doc.observaciones }}</div>{% endif %}

	<table style="width: 100%; margin-top: 50px"><tr>
		<td style="width: 45%; border-top: 1px solid #222; text-align: center; padding-top: 4px">Cajero</td>
		<td style="width: 10%"></td>
		<td style="width: 45%; border-top: 1px solid #222; text-align: center; padding-top: 4px">Revisado por</td>
	</tr></table>
</div>
